"""Derive SkyyPets/build_skyypets_0.4.23.py from SkyyPets 0.4.22 (SkyyPets/build_skyypets_0.4.22.py = the SET pin, itself GENERATED by
tools/pets_0_4_22_patch.py - never edit a generated script, edit this patch). Every anchor is asserted once; at the end every change is
undone on a copy and compared with 0.4.22 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/pets_0_4_23_patch.py   then   python SkyyPets/build_skyypets_0.4.23.py   (never --deploy)
      then  python SkyyPets/test_skyypets_0.4.23.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.23 (2026-11-03) = F WORKS ON PETS AGAIN - YOU CAN RIDE YOUR DRAGON (Skyy 2026-11-03: "i cant ride the dragon"; riding is designed:
  docs/answered/pets.md "when leveled up enough, you car ride and fly it too" + "the dragon is both a fighter and a mount").
  CAUSE: pets.passthrough = all (the 0.2.4 default) put the vanilla Intangible component on EVERY pet creature all the time. Intangible is
  synced to the client (IntangibleSystems$EntityTrackerUpdate -> IntangibleUpdate), and the client leaves an intangible entity out of its
  own targeting, so F never targets a pet: the server's UseEntityInteraction never runs for it, UseEntityEvent$Pre never fires, PetUseSys /
  PetViews.use / PetRide.request never run (Skyy's 2026-11-03 log: no "[Pets]" F line at all). F-to-pet had not worked since 0.2.4 either
  (the last "pet works" test was 0.2, 2026-10-10, before Intangible).
  FIX - "attacks pass through pets" without a permanent Intangible:
  1. Every pet keeps ProjectilePassthrough (Everything / Arrows and bolts): new-style projectiles skip it (EntityRefCollisionProvider).
  2. NEW damage cancel (PetGuardSys, damage Filter group, extended from summoned dragons to EVERY pet): with Everything, any hit on a pet
     whose source is a PLAYER (melee, area, ability, any projectile) is cancelled (PetViews.shield). Summoned dragons keep PetFight.guard
     (every hit cancelled, a mob's hit lowers its own pool - R6).
  3. Intangible only in FIGHTS (mode "ghost"): the engine's LEGACY projectiles (LaunchProjectile: staff / wand / spellbook orbs, the
     SkyyArmory bow blast, guns, thrown spears / knives) have no pass-through skip (EntityCollisionProvider.defaultEntityFilter never reads
     ProjectilePassthrough, Entity.isCollidable is always true), so with Everything a pet is Intangible for pets.passthrough.fight (8) s
     after its owner hits or is hit (DamageDataComponent last damage / last combat action) - EXCEPT a summon you can ride now (PetRide.canRide
     = a dragon at / above pets.dragon.rideLevel in the summon slot, a Horse): it is NEVER Intangible, so F always mounts it. Out of a fight
     every pet is tangible: F = "You pet ..." / ride. 0 = never Intangible (orbs then stop at a pet, harmlessly).
  WHAT INTANGIBLE ALSO DID: NPCs never detected an intangible creature (EntityDetectionUtil.isDetectableByNPCs). Now a pet is detectable
  outside fights: walking / flying pets are Invulnerable roles (a mob's hit does nothing - as in 0.2.0-0.2.3) and most vanilla mobs ignore
  other NPCs (DefaultNPCAttitude Ignore); a rideable dragon may be attacked by mobs it fights - the R6 design path that already ran with
  Arrows and bolts / Off (its own pool, DOWN at 0, back after the cooldown, nothing lost). Intangible also cancelled all damage
  (DamageSystems$FilterUnkillable) - covered by 2. (player hits) and the Invulnerable roles / PetFight.guard (mob hits).
  NEW ROW: Server Setup > Pets > "Pets ghost while you fight" (pets.passthrough.fight, 0-60 s, default 8, live). The ready line and
  /petadmin status name the mode, the cancels and the fight ghosts.
  SAVED DATA: none (the new row = its default when missing; no migration). No new class / system / command.
  ROLLBACK: SkyyPets 0.4.23 rolls back alone to 0.4.22 (= pets Intangible all the time again: F / riding broken, legacy shots pass).
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.22.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.23.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.22"') and P.has('s.equals("skyygear_mana")') and not P.has("PASS_FIGHT"), "not the generated SkyyPets 0.4.22 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.22 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_22_patch.py from SkyyPets 0.4.21
(build_skyypets_0.4.21.py, the SET pin, itself generated by tools/pets_0_4_21_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.22.py   -> SkyyPets/SkyyPets-0.4.22.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.22.py
''', '''"""SkyyPets 0.4.23 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_23_patch.py from SkyyPets 0.4.22
(build_skyypets_0.4.22.py, the SET pin, itself generated by tools/pets_0_4_22_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.23.py   -> SkyyPets/SkyyPets-0.4.23.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.23.py

''' + NOTE + '''
SkyyPets 0.4.22 (generated by tools/pets_0_4_22_patch.py from 0.4.21) - everything below is still true unless 0.4.23 above says otherwise:
''')
P.rep('VERSION = "0.4.22"\n', 'VERSION = "0.4.23"\n')

# ---- the new row (live, an int field PetsCfg.PASS_FIGHT)
P.rep('''     "", "live", "Everything = shots, swings, spells. Arrows and bolts = only arrows, bolts, thrown. Off = pets block.", "PASS",
     "java.lang.String"),
''', '''     "", "live", "Everything = shots, swings, spells. Arrows and bolts = only arrows, bolts, thrown. Off = pets block.", "PASS",
     "java.lang.String"),
    # 0.4.23 (Skyy: "i cant ride the dragon"): Intangible only this long after the owner fights - never on a summon you can ride
    ("pets.passthrough.fight", "Pets ghost while you fight", "show", "int", "8", "0", "60", "", "s", "live",
     "Everything: after you fight, pets (not a rideable dragon) let orbs, guns, throws pass. 0 = never.",
     "PASS_FIGHT", "int"),
''')

# ---- the engine member the fight check adds (ComponentAccessor.getResource; the DamageDataComponent / TimeResource members are probed)
P.rep('''             (T["CAC"], "getArchetype"), (T["CAC"], "tryRemoveComponent"), (T["ARCH"], "contains")):
    B.probe(pool, c, m)
''', '''             (T["CAC"], "getArchetype"), (T["CAC"], "tryRemoveComponent"), (T["ARCH"], "contains"),
             (T["CAC"], "getResource"), (T["DENT"], "getRef"), (T["DMG"], "getSource")):          # 0.4.23: PetViews.fightMs / shield
    B.probe(pool, c, m)
''')

# ---- PetWorld.passthrough: all = ProjectilePassthrough only (no Intangible any more); ghost = Intangible + ProjectilePassthrough
P.rep('''# 0.2.4: attacks pass through the creature. mode all = Intangible (out of every hit test: projectiles, swings, areas; synced to the client)
# + ProjectilePassthrough; shots = ProjectilePassthrough only; off = neither. Adds / removes only what differs (the archetype says what is
# there). Returns the mode now on it, null = not applied (no store / no creature / an engine error - upkeep tries again next second).
M(pwc, r"""
public static String passthrough(@CAC@ acc, @REF@ r, String mode) {
  if (API != null) return API.passthrough(acc, r, mode);
  if (acc == null || r == null || !r.isValid()) return null;
  String m = "off".equals(mode) || "shots".equals(mode) ? mode : "all";
''', '''# 0.2.4: attacks pass through the creature. 0.4.23: mode all / shots = ProjectilePassthrough only (the creature stays targetable: F
# works); ghost = Intangible (out of every hit test: legacy + new projectiles, swings, areas; synced to the client, so F cannot target it)
# + ProjectilePassthrough - only in a fight (PetViews.pass); off = neither. Adds / removes only what differs (the archetype says what is
# there). Returns the mode now on it, null = not applied (no store / no creature / an engine error - upkeep tries again next second).
M(pwc, r"""
public static String passthrough(@CAC@ acc, @REF@ r, String mode) {
  if (API != null) return API.passthrough(acc, r, mode);
  if (acc == null || r == null || !r.isValid()) return null;
  String m = "off".equals(mode) || "shots".equals(mode) || "ghost".equals(mode) ? mode : "all";
''')
P.rep('''    boolean wi = "all".equals(m);
    boolean wp = !"off".equals(m);
''', '''    boolean wi = "ghost".equals(m);          // 0.4.23: Intangible only for ghost (was: all)
    boolean wp = !"off".equals(m);
''')

# ---- PetViews.pass: the fight check + never Intangible on a summon you can ride; shield = the player-hit cancel on any pet
P.rep('''# once on spawn, then only when the setting changed (or the last try failed): one String compare a second per live creature
M(pvs, r"""
public static void pass(@CAC@ acc, @PKG@.PetView v) {
  if (v == null || v.ref == null) return;
  String m = v.riding ? "off" : passMode();          // 0.4.13 fix round: a ridden creature is normal (Dragon-Pet-Spec 4, probe D3)
  if (m.equals(v.passOn)) return;
  v.passOn = @PKG@.PetWorld.passthrough(acc, v.ref, m);
  if (v.passOn != null) PASS_SETS.incrementAndGet();
}""")
''', '''# 0.4.23: ms since the owner last hit or was hit (DamageDataComponent, the PetOps.combatMs reading on any accessor); -1 = never / unknown
F(pvs, "public static final java.util.concurrent.atomic.AtomicLong SHIELDS = new java.util.concurrent.atomic.AtomicLong();")
F(pvs, "public static final java.util.concurrent.atomic.AtomicLong GHOSTS = new java.util.concurrent.atomic.AtomicLong();")
M(pvs, r"""
public static long ago(java.time.Instant then, java.time.Instant now) {
  if (then == null || now == null) return -1L;
  try {
    long ms = java.time.Duration.between(then, now).toMillis();
    return ms < 0L ? -1L : ms;
  } catch (Throwable t) { return -1L; }
}""")
M(pvs, r"""
public static long fightMs(@CAC@ acc, @REF@ o) {
  if (acc == null || o == null || !o.isValid()) return -1L;
  try {
    @DDC@ dc = (@DDC@) acc.getComponent(o, @DDC@.getComponentType());
    if (dc == null) return -1L;
    @TIMR@ tr = (@TIMR@) acc.getResource(@TIMR@.getResourceType());
    java.time.Instant now = tr == null ? null : tr.getNow();
    long a = ago(dc.getLastDamageTime(), now);
    long b = ago(dc.getLastCombatAction(), now);
    if (a < 0L) return b;
    if (b < 0L) return a;
    return a < b ? a : b;
  } catch (Throwable t) { return -1L; }
}""")
M(pvs, r"""
public static boolean fighting(@CAC@ acc, @REF@ o) {
  int s = @PKG@.PetsCfg.PASS_FIGHT;
  if (s <= 0 || !"all".equals(passMode())) return false;
  long ms = fightMs(acc, o);
  return ms >= 0L && ms < (long) s * 1000L;
}""")
# once on spawn, then only when the mode changed (or the last try failed): one String compare a second per live creature.
# 0.4.23: all = ProjectilePassthrough only (targetable: F pets / mounts it); ghost (Intangible) only while the owner fights - and NEVER on a
# summon the owner can ride now (PetRide.canRide == null), so F always reaches a rideable dragon (Skyy 2026-11-03: "i cant ride the dragon")
M(pvs, r"""
public static void pass(@CAC@ acc, @PKG@.PetView v, boolean fight) {
  if (v == null || v.ref == null) return;
  String m = v.riding ? "off" : passMode();          // 0.4.13 fix round: a ridden creature is normal (Dragon-Pet-Spec 4, probe D3)
  if (fight && "all".equals(m) && @PKG@.PetRide.canRide(v) != null) m = "ghost";
  if (m.equals(v.passOn)) return;
  String was = v.passOn;
  v.passOn = @PKG@.PetWorld.passthrough(acc, v.ref, m);
  if (v.passOn != null) PASS_SETS.incrementAndGet();
  if ("ghost".equals(v.passOn) && !"ghost".equals(was)) GHOSTS.incrementAndGet();
}""")
M(pvs, "public static void pass(@CAC@ acc, @PKG@.PetView v) { pass(acc, v, false); }")
# 0.4.23: the live pet creature behind a store ref (identity, as PetFight.byRef; a few per player)
M(pvs, r"""
public static @PKG@.PetView byRef(@REF@ r) {
  if (r == null || LIVE.isEmpty()) return null;
  Object[] vs = LIVE.values().toArray();
  for (int i = 0; i < vs.length; i++) {
    @PKG@.PetView v = (@PKG@.PetView) vs[i];
    if (!v.gone && v.ref == r) return v;
  }
  return null;
}""")
# 0.4.23 damage Filter (PetGuardSys, after PetFight.guard): with Everything a PLAYER's hit on any pet (melee, area, ability, any shot) is
# cancelled - "all of your attacks should pass through them" without Intangible. A ridden creature is normal (as pass: off).
M(pvs, r"""
public static boolean shield(@CAC@ acc, @REF@ victim, @DMG@ d) {
  if (d == null || victim == null || d.isCancelled() || LIVE.isEmpty() || !"all".equals(passMode())) return false;
  @PKG@.PetView v = byRef(victim);
  if (v == null || v.riding) return false;
  Object src = d.getSource();
  if (!(src instanceof @DENT@)) return false;
  @REF@ a = ((@DENT@) src).getRef();
  if (a == null || a == victim || !a.isValid()) return false;
  if (@PKG@.PetFight.playerOf(acc, a) == null) return false;
  d.setCancelled(true);
  d.setAmount(0.0f);
  SHIELDS.incrementAndGet();
  return true;
}""")
M(pvs, r"""
public static String passText() {
  String m = passMode();
  if (!"all".equals(m)) return m;
  int s = @PKG@.PetsCfg.PASS_FIGHT;
  return "all (player hits on pets cancelled " + SHIELDS.get() + "; " + (s > 0 ? "out of every hit test " + s + " s after the owner fights, never a summon you can ride - fight ghosts " + GHOSTS.get() : "never out of the hit tests") + ")";
}""")
''')
P.rep('''  if (v.slot == 2) aura(v, cb);
  pass(cb, v);
  if (v.motion != 0) return;
''', '''  if (v.slot == 2) aura(v, cb);
  pass(cb, v, fighting(cb, o));          // 0.4.23: Intangible only in the owner's fights (never on a summon you can ride)
  if (v.motion != 0) return;
''')
P.rep('''role fallbacks " + FALLBACKS.get() + ". Visible pets " + (@PKG@.PetsCfg.VISIBLE ? "on" : "off") + ", roles " + @PKG@.PetsCfg.ROLE_WALK + " / " + @PKG@.PetsCfg.ROLE_FLY + ".";''',
      '''role fallbacks " + FALLBACKS.get() + ". Visible pets " + (@PKG@.PetsCfg.VISIBLE ? "on" : "off") + ", roles " + @PKG@.PetsCfg.ROLE_WALK + " / " + @PKG@.PetsCfg.ROLE_FLY + ". Attacks pass through pets: " + passText() + ".";''')

# ---- PetGuardSys: every pet (was: summoned dragons only)
P.rep('''    if (@PKG@.PetFight.DVIEWS.isEmpty() || !(ev instanceof @DMG@)) return;
    @PKG@.PetFight.guard(buf, chunk.getReferenceTo(idx), (@DMG@) ev);
  } catch (Throwable x) {
    if (!FAILED_ONCE) { FAILED_ONCE = true; @PKG@.PetsLog.warn("the dragon health hook failed (logged once): " + x); }''',
      '''    if (!(ev instanceof @DMG@) || (@PKG@.PetFight.DVIEWS.isEmpty() && @PKG@.PetViews.LIVE.isEmpty())) return;
    @REF@ r = chunk.getReferenceTo(idx);
    if (!@PKG@.PetFight.DVIEWS.isEmpty() && @PKG@.PetFight.guard(buf, r, (@DMG@) ev)) return;
    @PKG@.PetViews.shield(buf, r, (@DMG@) ev);          // 0.4.23: a player's hit on any pet (Everything)
  } catch (Throwable x) {
    if (!FAILED_ONCE) { FAILED_ONCE = true; @PKG@.PetsLog.warn("the pet damage hook failed (logged once): " + x); }''')

# ---- the ready line names the new pass-through
P.rep('''"; attacks pass through pets: " + @PKG@.PetViews.passMode() + "''', '''"; attacks pass through pets: " + @PKG@.PetViews.passText() + "''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0, "0.4.23 adds no class, system or command"
assert P.s.count('acc.putComponent(r, ti, @INTG@.INSTANCE)') == 1 and P.s.count('boolean wi = "ghost".equals(m);') == 1, "0.4.23: Intangible only in PetWorld.passthrough, only for ghost"
assert P.s.count('m = "ghost";') == 1, "0.4.23: one place picks ghost (PetViews.pass)"
P.finish()
